package com.palletpilot.wcs.application.dto;

import lombok.Builder;
import lombok.Data;
import java.util.UUID;

/**
 * Recommendation to re-slot a pallet from its current zone to a better zone.
 * Generated by SlottingOptimizationService.generateReSlottingRecommendations().
 */
@Data
@Builder
public class ReSlottingRecommendation {
    private UUID palletId;
    private String palletDisplayId;
    private String sku;
    private String currentZone;
    private String expectedZone;
    private UUID currentLocationId;
    private double priorityScore;
    private String reason;
}
